import sys,os
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from helper import setup,add,addm,run
setup('R 300.10','Formulare, Ziff.')
F="Das EBU ist befugt, sein Unternehmenslogo in den Formularen zu verwenden. Änderungen in der Darstellung oder im Format der Formulare kann es in eigener Kompetenz vornehmen. Sind in den Formularen JA-/NEIN-Fragen vorgesehen, müssen immer das JA- und das NEIN-Feld aufgeführt werden. Das zutreffende Feld ist in jedem Fall anzukreuzen. Sind in den Formularen Auswahlmöglichkeiten vorgesehen, müssen die entsprechenden Auswahlfelder aufgeführt werden. Das zutreffende Auswahlfeld ist in jedem Fall anzukreuzen. Pro Formular darf nur ein Befehl angeordnet werden, nötigenfalls ist dieser im entsprechenden Feld mittels zusätzlicher Anordnungen für die gleiche Situation zu ergänzen."
add("1.1","Logo","Was ist das EBU gemäss § in Bezug auf die Formulare befugt?","Sein Unternehmenslogo zu verwenden und Darstellung oder Format in eigener Kompetenz zu ändern.",["Nummern und Feldbezeichnungen der Befehle zu ändern.","Neue Felder auf den Befehlen aufzunehmen.","Den Inhalt der Befehle frei zu bestimmen."],F)
add("1.1","JA-/NEIN-Fragen","Was gilt gemäss § für JA-/NEIN-Fragen in den Formularen?","Das JA- und das NEIN-Feld müssen aufgeführt sein und das zutreffende Feld ist in jedem Fall anzukreuzen.",["Nur das zutreffende Feld wird aufgeführt.","Nur das JA-Feld wird angekreuzt, das NEIN-Feld bleibt leer.","Das Ankreuzen ist freiwillig."],F)
add("1.1","Auswahlfelder","Was gilt gemäss § für Auswahlmöglichkeiten in den Formularen?","Die Auswahlfelder müssen aufgeführt sein und das zutreffende Feld ist in jedem Fall anzukreuzen.",["Nur das gewählte Feld wird aufgeführt.","Das zutreffende Feld wird unterstrichen.","Das Ankreuzen ist nur bei Befehlen nötig."],F)
add("1.1","Ein Befehl pro Formular","Wie viele Befehle dürfen gemäss § pro Formular angeordnet werden?","Nur ein Befehl.",["Höchstens zwei Befehle.","Beliebig viele Befehle.","Höchstens drei Befehle der gleichen Art."],F)
add("1.1","Zusätzliche Anordnungen","Wie sind zusätzliche Anordnungen für die gleiche Situation gemäss § nötigenfalls zu übermitteln?","Im entsprechenden Feld des Befehls als Ergänzung.",["Auf einem zweiten Formular.","Mündlich ohne Aufzeichnung.","Auf der Rückseite des Formulars."],F)
F="Die Formulare sind nach Inhalten in drei Kategorien eingeteilt. Sie sind in der Mustersammlung aufgeführt."
add("2","Kategorien","In wie viele Kategorien sind die Formulare gemäss § nach Inhalten eingeteilt?","In drei Kategorien.",["In zwei Kategorien.","In vier Kategorien.","In fünf Kategorien."],F)
add("2","Mustersammlung","Wo sind die Formulare der drei Kategorien gemäss § aufgeführt?","In der Mustersammlung.",["In den Betriebsvorschriften der ISB.","Im Fahrplan.","In der Streckentabelle."],F)
F="Zu den Formularen der ersten Kategorie zählen: die Formulare Befehl (Befehle 1, 3, 4, 5, 6, 8 und 9) und der Befehl für Kreuzung und Überholung. Die entsprechende Bezeichnung ist als Titel zu verwenden. Die einzelnen Befehle sind systemisch aufgebaut und durchnummeriert. Die dem jeweiligen Befehl zugeordnete Nummer des Befehls sowie die Nummerierung und Bezeichnungen der Felder, gemäss Mustersammlung, dürfen nicht geändert werden. Wenn ein quittungspflichtiger Befehl protokollpflichtig abgegeben oder übermittelt wird, ist das entsprechende Formular Befehl zu verwenden. Die Befehle in den Zirkularen sind gleichwertig wie die Befehle in den Formularen der ersten Kategorie."
addm("2.1","Erste Kategorie","Was zählt gemäss § zu den Formularen der ersten Kategorie (Mehrfachauswahl).",["Die Formulare Befehl (Befehle 1, 3, 4, 5, 6, 8 und 9)","Der Befehl für Kreuzung und Überholung"],["Der Bremszettel","Die Fahrordnung für Züge","Die Streckentabelle"],F)
add("2.1","Titel Formulare erste Kategorie","Was ist bei den Formularen der ersten Kategorie gemäss § als Titel zu verwenden?","Die entsprechende Bezeichnung des Befehls.",["Der Name des EBU.","Die Nummer des Zuges.","Der Name der Strecke."],F)
addm("2.1","Nicht änderbar","Was darf bei den Befehlen der ersten Kategorie gemäss § nicht geändert werden (Mehrfachauswahl).",["Die dem Befehl zugeordnete Nummer","Die Nummerierung der Felder gemäss Mustersammlung","Die Bezeichnungen der Felder gemäss Mustersammlung"],["Das Unternehmenslogo","Das Format des Formulars"],F)
add("2.1","Quittungspflichtig protokollpflichtig","Welches Formular ist gemäss § zu verwenden, wenn ein quittungspflichtiger Befehl protokollpflichtig abgegeben oder übermittelt wird?","Das entsprechende Formular Befehl.",["Ein Zirkular.","Ein frei gestaltetes Formular.","Der Bremszettel."],F)
add("2.1","Zirkulare","Wie sind die Befehle in den Zirkularen gemäss § gegenüber den Befehlen der ersten Kategorie zu betrachten?","Sie sind gleichwertig.",["Sie sind nachrangig.","Sie sind nur Empfehlungen.","Sie sind nur bei Störungen gültig."],F)
add("2.1.1","Inhalt erste Kategorie","Was enthalten die Formulare der ersten Kategorie gemäss §?","Befehle mit den verbindlich vorgeschriebenen Inhalten.",["Meldungen mit bedingt verbindlichem Textinhalt.","Bedingt verbindliche Angaben.","Nur unternehmensspezifische Informationen."],"Die Formulare der ersten Kategorie enthalten Befehle mit den verbindlich vorgeschriebenen Inhalten. Die Nachvollziehbarkeit der Übermittlung muss gewährleistet sein.")
F="Einzelne nie verwendete Befehle oder Teile davon können weggelassen werden. Die Reihenfolge der Befehle kann geändert werden, sofern sich dadurch für das EBU Vorteile ergeben."
addm("2.1.2","Wegfall und Reihenfolge","Was ist gemäss § bei den Befehlen zulässig (Mehrfachauswahl).",["Einzelne nie verwendete Befehle oder Teile davon wegzulassen","Die Reihenfolge der Befehle zu ändern, sofern sich dadurch für das EBU Vorteile ergeben"],["Die Nummern der Befehle zu ändern","Neue Befehle ohne Nummer einzuführen"],F)
F="Die Nummern 1 bis 20 sind für europäisch harmonisierte Befehle reserviert. Nationale und allfällige durch die ISB zu definierende Befehle sind ab 21 zu nummerieren. Die in den FDV verwendeten Nummern sind verbindlich."
add("2.1.3","Nummern 1 bis 20","Wofür sind die Nummern 1 bis 20 gemäss § reserviert?","Für europäisch harmonisierte Befehle.",["Für nationale Befehle.","Für Befehle der ISB.","Für Befehle der EBU."],F)
add("2.1.3","Nummern ab 21","Wie sind nationale und allfällige durch die ISB zu definierende Befehle gemäss § zu nummerieren?","Ab 21.",["Ab 11.","Ab 41.","Ab 100."],F)
F="Die einzelnen auszufüllenden Felder haben eine eindeutige Bezeichnung. Felder, die nicht erforderlich sind, dürfen auf dem Formular weggelassen werden. Neue oder zusätzliche Felder dürfen nicht auf die Befehle aufgenommen werden. Die ISB legen die Inhalte der eindeutigen Identifikation (Feld Z) in den Betriebsvorschriften fest."
add("2.1.4","Felder weglassen","Was gilt gemäss § für nicht erforderliche Felder auf den Befehlen 1–20?","Sie dürfen auf dem Formular weggelassen werden.",["Sie müssen leer ausgefüllt werden.","Sie müssen durchgestrichen werden.","Sie dürfen nicht weggelassen werden."],F)
add("2.1.4","Neue Felder","Dürfen gemäss § neue oder zusätzliche Felder auf die Befehle 1–20 aufgenommen werden?","Nein, neue oder zusätzliche Felder dürfen nicht aufgenommen werden.",["Ja, in eigener Kompetenz des EBU.","Ja, mit Zustimmung der ISB.","Ja, aber nur bei Befehl 6."],F)
add("2.1.4","Feld Z","Wer legt gemäss § die Inhalte der eindeutigen Identifikation (Feld Z) in den Betriebsvorschriften fest?","Die ISB.",["Das EBU.","Das BAV.","Der FDL."],F)
F="Zu den Formularen der zweiten Kategorie zählen: der Bremszettel (Angaben für die Zugführung), die Fahrordnung für Züge, die Fahrordnung für Rangierbewegungen auf die Strecke, die Anzeige einer Gleissperrung. Die entsprechende Bezeichnung ist als Titel zu verwenden. Die Formulare enthalten keine nummerierten Module. Sie werden in der Regel fallbezogen übermittelt."
addm("2.2","Zweite Kategorie","Was zählt gemäss § zu den Formularen der zweiten Kategorie (Mehrfachauswahl).",["Der Bremszettel (Angaben für die Zugführung)","Die Fahrordnung für Züge","Die Fahrordnung für Rangierbewegungen auf die Strecke","Die Anzeige einer Gleissperrung"],["Die gedruckte Fahrordnung","Die Streckentabelle","Der Befehl 6"],F)
add("2.2","Nummerierte Module","Was gilt gemäss § für nummerierte Module bei den Formularen der zweiten Kategorie?","Die Formulare enthalten keine nummerierten Module.",["Sie enthalten nummerierte Module ab 21.","Sie enthalten nummerierte Module von 1 bis 20.","Sie enthalten nur nummerierte Module für Extrazüge."],F)
add("2.2","Übermittlung zweite Kategorie","Wie werden die Formulare der zweiten Kategorie gemäss § in der Regel übermittelt?","Fallbezogen.",["Frühzeitig vor Betriebsbeginn.","Jährlich.","Nur schriftlich im Voraus."],F)
F="Die Formulare der zweiten Kategorie enthalten Meldungen mit bedingt verbindlichem Textinhalt. Die in den Vorschriften vorgesehenen Inhalte sowie die erforderlichen Angaben (z.B. für Extrazüge) sind zu verwenden. Die Nachvollziehbarkeit der Übermittlung muss gewährleistet sein."
add("2.2.1","Inhalt zweite Kategorie","Was enthalten die Formulare der zweiten Kategorie gemäss §?","Meldungen mit bedingt verbindlichem Textinhalt.",["Befehle mit verbindlich vorgeschriebenem Inhalt.","Nur unternehmensspezifische Informationen.","Nur Angaben für Extrazüge."],F)
F="Zu den Formularen der dritten Kategorie zählen: gedruckte Fahrordnung, Streckentabelle. Auf Grund des Titels muss der entsprechende Verwendungszweck ersichtlich sein. Diese Formulare werden in der Regel frühzeitig abgegeben."
addm("2.3","Dritte Kategorie","Was zählt gemäss § zu den Formularen der dritten Kategorie (Mehrfachauswahl).",["Die gedruckte Fahrordnung","Die Streckentabelle"],["Der Bremszettel","Die Anzeige einer Gleissperrung","Die Fahrordnung für Rangierbewegungen auf die Strecke"],F)
add("2.3","Abgabe dritte Kategorie","Wann werden die Formulare der dritten Kategorie gemäss § in der Regel abgegeben?","Frühzeitig.",["Fallbezogen.","Erst bei Fahrtbeginn.","Nur auf Verlangen des LF."],F)
F="Die Formulare der dritten Kategorie enthalten bedingt verbindliche Angaben. Die in den Vorschriften vorgesehenen Inhalte (z.B. Angaben in der Fahrordnung und Streckentabelle) sind zu verwenden. Weitere Ergänzungen sowie unternehmensspezifische Informationen können die EBU in eigener Kompetenz vornehmen."
add("2.3.1","Inhalt dritte Kategorie","Was enthalten die Formulare der dritten Kategorie gemäss §?","Bedingt verbindliche Angaben.",["Befehle mit verbindlich vorgeschriebenen Inhalten.","Meldungen mit nummerierten Modulen.","Nur Meldungen für Extrazüge."],F)
add("2.3.1","Ergänzungen EBU","Was können die EBU bei den Formularen der dritten Kategorie gemäss § in eigener Kompetenz vornehmen?","Weitere Ergänzungen sowie unternehmensspezifische Informationen.",["Eine Änderung der vorgeschriebenen Inhalte.","Eine Änderung der Befehlsnummern.","Eine Streichung der vorgeschriebenen Inhalte."],F)
F="Formulare Befehl: Befehl 1: Vorbeifahrt an Halt zeigenden Signalen; Befehl 3: Anordnung im Stillstand bleiben; Befehl 4: Widerruf eines Befehls; Befehl 5: Verminderung der Geschwindigkeit; Befehl 6: Fahren mit Fahrt auf Sicht; Befehl 8: Befahren einer oder mehrerer gestörter Bahnübergangsanlagen; Befehl 9: Fahrt mit eingeschränkter Stromversorgung. Befehl für Kreuzung und Überholung: Befehl 41: Ausserordentliche oder fakultative Kreuzung; Befehl 42: Ausserordentliche oder fakultative Überholung; Befehl 43: Ausfall einer Kreuzung oder einer Überholung; Befehl 44: Kreuzungsverlegung."
add("3.1","Befehl 1","Wie lautet die Bezeichnung des Befehls 1 gemäss §?","Vorbeifahrt an Halt zeigenden Signalen.",["Anordnung im Stillstand bleiben.","Fahren mit Fahrt auf Sicht.","Widerruf eines Befehls."],F)
add("3.1","Befehl 3","Wie lautet die Bezeichnung des Befehls 3 gemäss §?","Anordnung im Stillstand bleiben.",["Vorbeifahrt an Halt zeigenden Signalen.","Verminderung der Geschwindigkeit.","Fahrt mit eingeschränkter Stromversorgung."],F)
add("3.1","Befehl 4","Wie lautet die Bezeichnung des Befehls 4 gemäss §?","Widerruf eines Befehls.",["Verminderung der Geschwindigkeit.","Anordnung im Stillstand bleiben.","Kreuzungsverlegung."],F)
add("3.1","Befehl 5","Wie lautet die Bezeichnung des Befehls 5 gemäss §?","Verminderung der Geschwindigkeit.",["Fahren mit Fahrt auf Sicht.","Widerruf eines Befehls.","Befahren gestörter Bahnübergangsanlagen."],F)
add("3.1","Befehl 6","Wie lautet die Bezeichnung des Befehls 6 gemäss §?","Fahren mit Fahrt auf Sicht.",["Verminderung der Geschwindigkeit.","Vorbeifahrt an Halt zeigenden Signalen.","Fahrt mit eingeschränkter Stromversorgung."],F)
add("3.1","Befehl 8","Wie lautet die Bezeichnung des Befehls 8 gemäss §?","Befahren einer oder mehrerer gestörter Bahnübergangsanlagen.",["Fahrt mit eingeschränkter Stromversorgung.","Fahren mit Fahrt auf Sicht.","Ausfall einer Kreuzung oder einer Überholung."],F)
add("3.1","Befehl 9","Wie lautet die Bezeichnung des Befehls 9 gemäss §?","Fahrt mit eingeschränkter Stromversorgung.",["Befahren gestörter Bahnübergangsanlagen.","Verminderung der Geschwindigkeit.","Anordnung im Stillstand bleiben."],F)
add("3.1","Befehl 41","Wie lautet die Bezeichnung des Befehls 41 gemäss §?","Ausserordentliche oder fakultative Kreuzung.",["Ausserordentliche oder fakultative Überholung.","Ausfall einer Kreuzung oder einer Überholung.","Kreuzungsverlegung."],F)
add("3.1","Befehl 42","Wie lautet die Bezeichnung des Befehls 42 gemäss §?","Ausserordentliche oder fakultative Überholung.",["Ausserordentliche oder fakultative Kreuzung.","Ausfall einer Kreuzung oder einer Überholung.","Kreuzungsverlegung."],F)
add("3.1","Befehl 43","Wie lautet die Bezeichnung des Befehls 43 gemäss §?","Ausfall einer Kreuzung oder einer Überholung.",["Kreuzungsverlegung.","Ausserordentliche oder fakultative Kreuzung.","Ausserordentliche oder fakultative Überholung."],F)
add("3.1","Befehl 44","Wie lautet die Bezeichnung des Befehls 44 gemäss §?","Kreuzungsverlegung.",["Ausfall einer Kreuzung oder einer Überholung.","Ausserordentliche oder fakultative Kreuzung.","Ausserordentliche oder fakultative Überholung."],F)
addm("3.1","Befehle Kreuzung Überholung","Welche Befehle gehören gemäss § zum Befehl für Kreuzung und Überholung (Mehrfachauswahl).",["Befehl 41","Befehl 42","Befehl 43","Befehl 44"],["Befehl 3","Befehl 5","Befehl 9"],F)
F="Formulare der zweiten Kategorie: der Bremszettel (Angaben für die Zugführung), Fahrordnung für Züge, Fahrordnung für Rangierbewegungen auf die Strecke, Anzeige einer Gleissperrung. Der Bremszettel enthält u.a. Angaben zu Datum, Zug, von/nach, begleitet (ja/nein), Triebfahrzeug(e), Anhängelast und Gesamtzug mit Zug- und Bremsreihe, v max., Länge, Gewicht, Bremsgewicht, Festhaltekraft, Bremsart-Wechsel, Gefahrgut (ja/nein), zusätzlichen Angaben sowie «Notiert, der Beauftragte (Name + Datum)»."
addm("3.2","Bremszettel Angaben","Welche Angaben enthält der Bremszettel gemäss § (Mehrfachauswahl).",["Zug- und Bremsreihe","Länge und Gewicht","Bremsgewicht","Festhaltekraft","Gefahrgut (ja/nein)"],["Kilometrierung der Bahn","Name des Fahrdienstleiters"],F)
add("3.2","Bremszettel Titel","Wie lautet der Titel des Formulars der zweiten Kategorie mit den Angaben für die Zugführung gemäss §?","Bremszettel (Angaben für die Zugführung).",["Fahrordnung für Züge.","Streckentabelle.","Anzeige einer Gleissperrung."],F)
add("3.2","Bremszettel Notiert","Wer notiert gemäss § auf dem Bremszettel mit Name und Datum?","Der Beauftragte.",["Der FDL.","Der ZVB.","Der technische Dienst."],F)
F="Formulare der dritten Kategorie: Musterseite Fahrordnung, Musterseite Streckentabelle. Die Streckentabelle enthält u.a. Signale der Block- und Spurwechselstellen, Pfeiftafeln, Kilometrierung der Bahn, massgebende Gefälle und Steigung, Kommunikationskanal und Bremsverhältnis in %."
addm("3.3","Streckentabelle Angaben","Welche Angaben enthält die Musterseite der Streckentabelle gemäss § (Mehrfachauswahl).",["Kilometrierung der Bahn","Massgebende Gefälle und Steigungen","Kommunikationskanal","Bremsverhältnis in %"],["Anzahl Wagen","Festhaltekraft des Zuges"],F)
